import{d as h,C as r,o as g,c as u,j as i,a as e,E as a,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"中庸·第29章","description":"《中庸》第 29 章——王天下有三重：本诸身、征诸庶民、考诸三王、建诸天地、质诸鬼神、百世以俟圣人；动而世为天下道。","frontmatter":{"title":"中庸·第29章","description":"《中庸》第 29 章——王天下有三重：本诸身、征诸庶民、考诸三王、建诸天地、质诸鬼神、百世以俟圣人；动而世为天下道。","category":"guide","aliases":["第29章","中庸第29章","三重"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-29.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-29.md","lastUpdated":1790316338000}'),d={name:"lizhimingde/sishu-wujing/zhongyong/chapter-29.md"},b=h({...d,setup(p){const o=[{id:"sanchong",label:"王天下有三重 · 上焉者虽善无征 · 下焉者虽善不尊",showLabel:!0,sentences:[["王天下有三重焉，其",{text:"寡过",glossary:"guaguo"},"矣乎！上焉者虽善",{text:"无征",glossary:"wuzheng"},"，无征不信，不信民弗从；下焉者虽善",{text:"不尊",glossary:"buzun"},"，不尊不信，不信民弗从。"]],note:"「王天下有三重焉」（三重＝议礼、制度、考文三事），能行此三者，「其寡过矣乎」。反之：「上焉者虽善无征」——上古之礼虽善，却无实据可征，无征则不信，不信则民不从；「下焉者虽善不尊」——身在下位者其礼虽善而位不尊，不尊则不信，民亦不从。"},{id:"liuchong",label:"本诸身 · 征诸庶民 · 考诸三王 · 建诸天地 · 质诸鬼神 · 百世俟圣人",showLabel:!0,sentences:[["故君子之道：",{text:"本诸身",glossary:"benzhushen"},"，",{text:"征诸庶民",glossary:"zhengzhushumin"},"，考诸三王而不",{text:"缪",glossary:"mou"},"，建诸天地而不悖，质诸鬼神而无",{text:"疑",glossary:"zhiyizhu"},"，百世以俟圣人而不惑。"],["质诸鬼神而无疑，知天也；百世以俟圣人而不惑，知人也。"]],note:"君子之道的六项检验：「本诸身」（本于自身），「征诸庶民」（征验于百姓），「考诸三王而不缪」（考之三代之王而无误），「建诸天地而不悖」，「质诸鬼神而无疑」，「百世以俟圣人而不惑」。后二句又作解释：「质诸鬼神而无疑，知天也；百世以俟圣人而不惑，知人也。」"},{id:"weize",label:"动而世为天下道 · 远之则有望，近之则不厌",showLabel:!0,sentences:[["是故君子动而世为天下道，行而世为天下法，言而世为天下则。远之则有望，近之则不厌。"]],note:"「是故君子动而世为天下道，行而世为天下法，言而世为天下则」——其动为天下所遵循，其行为天下所取法，其言为天下所准则。故「远之则有望，近之则不厌」——远望则有仰慕，近处则不觉厌倦。"},{id:"yongyu",label:"在彼无恶，在此无射 · 未有不如此而蚤有誉",showLabel:!0,sentences:[["《诗》曰：“在彼无恶，在此无",{text:"射",glossary:"yiyi"},"；庶几",{text:"夙夜",glossary:"suye"},"，以永终誉！”君子未有不如此而",{text:"蚤",glossary:"zao"},"有誉于天下者也。"]],note:"引《诗》「在彼无恶，在此无射（射＝厌）；庶几夙夜，以永终誉」——在彼无人厌恶，在此无人厌弃；几乎从早到晚，永保美誉。故曰「君子未有不如此而蚤有誉于天下者也」——未有不行此道而早得天下声誉的。"}],s=[{id:"guaguo",term:"寡过",pinyin:"guǎ guò",meaning:"少犯过失。吕氏曰：「三重，谓议礼、制度、考文。惟天子得以行之，则国不异政，家不殊俗，而人得寡过矣。」"},{id:"wuzheng",term:"无征",pinyin:"wú zhēng",meaning:"无从考据、没有凭证。朱注：「上焉者，谓时王以前，如夏、商之礼虽善，而皆不可考。」"},{id:"buzun",term:"不尊",pinyin:"bù zūn",meaning:"不在尊位。朱注：「下焉者，谓圣人在下，如孔子虽善于礼，而不在尊位也。」"},{id:"benzhushen",term:"本诸身",pinyin:"běn zhū shēn",meaning:"本之于自身。朱注：「本诸身，有其德也。」——六重验证的第一条。"},{id:"zhengzhushumin",term:"征诸庶民",pinyin:"zhēng zhū shù mín",meaning:"在百姓身上验证。朱注：「验其所信从也。」"},{id:"mou",term:"不缪",pinyin:"bù miù",meaning:"不谬、不差。缪：同「谬」。"},{id:"zhiyizhu",term:"质诸鬼神而无疑",pinyin:"zhì zhū guǐ shén",meaning:"质：质证。朱注：「质诸鬼神而无疑，知天也。」"},{id:"yiyi",term:"无射",pinyin:"wú yì",meaning:"射：读 yì，厌。无射，即不厌。《诗·周颂·振鹭》作「斁」。"},{id:"suye",term:"夙夜",pinyin:"sù yè",meaning:"早夜、日夜。庶几夙夜，谓日夜勤勉。"},{id:"zao",term:"蚤",pinyin:"zǎo",meaning:"同「早」。"}];return(y,n)=>{const l=r("DaoTextReading"),t=r("DaoKeywordCards");return g(),u("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第29章",tabindex:"-1"},[e("中庸·第29章 "),i("a",{class:"header-anchor",href:"#中庸·第29章","aria-label":'Permalink to "中庸·第29章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[e("第二十九章说「王天下有三重」（议礼、制度、考文），并给出"),i("strong",null,"六重验证"),e("——本诸身、征诸庶民、考诸三王、建诸天地、质诸鬼神、百世以俟圣人；末以「动而世为天下道」与《诗》句作结。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),a(l,{colophon:"王天下有三重 · 六重验证 · 世为天下道",tone:"ink",sections:o,glossary:s,"default-mode":"slips","aria-label":"中庸·第29章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(t,{items:[{term:"三重",pinyin:["sān","chóng"],meaning:"吕氏注：谓议礼、制度、考文三事。惟天子得行之，则「国不异政，家不殊俗，而人得寡过」。"},{term:"上焉者",pinyin:["shàng","yān","zhě"],meaning:"时王以前——夏商之礼虽善，而不可考。"},{term:"下焉者",pinyin:["xià","yān","zhě"],meaning:"圣人在下——如孔子虽善于礼，而不在尊位。"},{term:"本诸身",pinyin:["běn","zhū","shēn"],meaning:"本之于己身——有其德。"},{term:"征诸庶民",pinyin:["zhēng","zhū","shù","mín"],meaning:"验证于百姓——验其信从。"},{term:"考诸三王",pinyin:["kǎo","zhū","sān","wáng"],meaning:"考校于三代之王而不差。"},{term:"建诸天地",pinyin:["jiàn","zhū","tiān","dì"],meaning:"立于天地而不悖。"},{term:"质诸鬼神",pinyin:["zhì","zhū","guǐ","shén"],meaning:"质证于鬼神而不疑。"},{term:"百世俟圣人",pinyin:["bǎi","shì","sì","shèng","rén"],meaning:"等百世之后的圣人也不惑。四者与前二合为六重验证。"}]}),a(t,{items:[{term:"动而世为天下道",pinyin:["dòng","ér","shì","wéi"],meaning:"一举一动，世世代代成为天下的道路；行成为法度，言成为准则。"},{term:"远之则有望",pinyin:["yuǎn","zhī","zé","yǒu","wàng"],meaning:"距离远时令人有企慕。"},{term:"近之则不厌",pinyin:["jìn","zhī","zé","bù","yàn"],meaning:"距离近时令人不厌烦——信誉的两种距离。"},{term:"无射",pinyin:["wú","yì"],meaning:"射：读 yì，厌。无射，即不厌。"},{term:"夙夜",pinyin:["sù","yè"],meaning:"早夜、日夜。"}]}),n[4]||(n[4]=m('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>王天下有三重</strong>：治理天下有三件重要的事，做到了，过失就少了！在上位的（前代）虽好，但无从考据，无从考据就不可信，不可信百姓就不遵从；在下位的（圣人）虽好，但不在尊位，不在尊位就不可信，不可信百姓也不遵从。</p><p><strong>六重验证</strong>：所以君子之道：本之于自身，验证于百姓，考校于三代之王而不差，立于天地而不违背，质证于鬼神而不疑惑，等百世之后的圣人出现也不迷惑。质证鬼神而无嫌，是知天；百世俟圣人而不惑，是知人。</p><p><strong>世为天下道</strong>：所以君子一动，世世代代成为天下的道路；一行，成为天下的法度；一言，成为天下的准则。远望他令人有企慕，近处他令人不厌烦。</p><p><strong>在彼无恶</strong>：《诗经》说：「在那边无人厌弃，在这边也无人厌烦；愿日夜勤勉，以永保终身的令誉！」君子没有不这样做而能早在天下有声誉的。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第二十九章承接上章的制度话题，先立「三重」（议礼、制度、考文），再讲两端的困难——上焉者无征、下焉者不尊；然后给出<strong>六重验证</strong>，最后落在「动而世为天下道，行而世为天下法，言而世为天下则」与《诗》句。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>「上焉者无征，下焉者不尊」是一组对称的两难</strong>：前代之法虽好，但无从考据；在下之圣虽好，但不在其位。<strong>两者都不可信，都难行。</strong> 这一组对照把第 28 章「德位相配」说透了。</li><li><strong>六重验证是全篇最完整的一张检验清单</strong>：由近及远——自身 → 百姓 → 三代之王 → 天地 → 鬼神 → 百世之后的圣人。<strong>每一重都是一个可能的反证点。</strong></li><li><strong>「知天」「知人」是六重的收束</strong>：质诸鬼神而无疑（知天）、百世俟圣人而不惑（知人）。一上一下，都归于「知理」。</li><li><strong>「动而世为天下道，行而世为天下法，言而世为天下则」是极高也极重的表述</strong>：一个人的言行成为后世的准则。本章接下章（第 30 章「仲尼祖述尧舜」），讲的正是这件事。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>六重当检验清单用</strong>：我要推的一件事，经得起「自身、他人、前人、理、不明者、后来人」这六重检验吗？最经不起哪一重？</li><li><strong>「本诸身」排第一</strong>：所有检验的起点，还是自己有没有那个德。</li><li><strong>「远之则有望，近之则不厌」</strong>：真正的信誉，在远看和近看时都成立。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>治理天下有三件大事——议礼、制度、考文，做好了，过失就少。</p><p>但这里有它的难处：<strong>老的规矩虽好，却无从考据</strong>（不可信）；<strong>在下面的人虽好，却不在其位</strong>（不可信）。两边都推不动。</p><p>所以君子的道要过六道关：<strong>本之于自身，验证于百姓，考校于三代之王而不差，立于天地而不违背，质证于鬼神而不疑，等百世之后的圣人也不惑。</strong></p><p>过了这六关，他的一举一动、一行一言，就成了天下的道、法、则——<strong>远看令人向往，近看令人不厌。</strong></p><p>这一章给的不是大话，是一张校验表。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>六重验证（身／民／三王／天地／鬼神／百世）——我要推的事，最经不起哪一重？</li><li>「本诸身」为什么排在第一位？</li><li>「远之则有望，近之则不厌」——我在远处的名声与近处的相处，一致吗？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-28">中庸·第28章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-30">中庸·第30章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',25))])}}});export{c as __pageData,b as default};
